def update_file(file_path, translations):
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    updated_count = 0
    
    # Regex to find each POI object
    poi_pattern = re.compile(r'\{[^{]*?id:\s*"(.*?)",.*?\}', re.DOTALL)
    
    def replacer(match):
        nonlocal updated_count
        poi_content = match.group(0)
        poi_id = match.group(1)
        
        if poi_id in translations:
            trans = translations[poi_id]
            
            # Update descriptionAdvanced
            desc_match = re.search(r'descriptionAdvanced:\s*\{(.*?)\}', poi_content, re.DOTALL)
            if desc_match:
                desc_obj = desc_match.group(1)
                if 'ro: ""' in desc_obj:
                    new_desc_obj = desc_obj.replace('ro: ""', f'ro: "{trans["desc"]}"')
                    poi_content = poi_content.replace(desc_obj, new_desc_obj)
                    updated_count += 0.5 # Track partial update
            else:
                # Add descriptionAdvanced if missing
                desc_block = f',\n    descriptionAdvanced: {{\n      de: "",\n      hu: "",\n      ro: "{trans["desc"]}",\n      en: ""\n    }}'
                # Find a good place to insert - after facts object or before the end of the POI object
                if 'facts: {' in poi_content:
                    # Find the end of the facts block
                    facts_end = poi_content.find('}', poi_content.find('facts: {')) + 1
                    poi_content = poi_content[:facts_end] + desc_block + poi_content[facts_end:]
                else:
                    # Just before the last }
                    last_brace = poi_content.rfind('}')
                    poi_content = poi_content[:last_brace].rstrip() + desc_block + "\n  " + poi_content[last_brace:]
                updated_count += 0.5

            # Update factsAdvanced
            facts_match = re.search(r'factsAdvanced:\s*\{(.*?)\}', poi_content, re.DOTALL)
            if facts_match:
                facts_obj = facts_match.group(1)
                if 'ro: []' in facts_obj:
                    facts_json = '[\n        ' + ',\n        '.join([f'"{f}"' for f in trans["facts"]]) + '\n      ]'
                    new_facts_obj = facts_obj.replace('ro: []', f'ro: {facts_json}')
                    poi_content = poi_content.replace(facts_obj, new_facts_obj)
                    updated_count += 0.5
            else:
                # Add factsAdvanced if missing
                facts_json = '[\n        ' + ',\n        '.join([f'"{f}"' for f in trans["facts"]]) + '\n      ]'
                facts_block = f',\n    factsAdvanced: {{\n      de: [],\n      hu: [],\n      ro: {facts_json},\n      en: []\n    }}'
                # Just before the last }
                last_brace = poi_content.rfind('}')
                poi_content = poi_content[:last_brace].rstrip() + facts_block + "\n  " + poi_content[last_brace:]
                updated_count += 0.5
        
        return poi_content

    new_content = poi_pattern.sub(replacer, content)
    
    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(new_content)
    
    return int(updated_count)

